import type { BankQuestion } from "@/lib/bank";

/** Modern Physics and Semiconductors (Physics (JEE/NEET)): 127 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-modern-physics-1","question":"In the photoelectric effect, increasing the intensity of the incident light (frequency kept above threshold and unchanged) increases the:","options":["Maximum kinetic energy of the photoelectrons","Stopping potential","Photoelectric current","Work function of the metal"],"answer":2,"explanation":"Intensity fixes the number of photons per second, hence the number of electrons emitted per second (the photocurrent). The maximum kinetic energy and stopping potential depend only on frequency; the work function is a property of the metal.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-modern-physics-2","question":"The radius of the first Bohr orbit of the hydrogen atom is approximately:","options":["0.53 nm","0.53 Å","5.3 Å","1.06 Å"],"answer":1,"explanation":"a₀ = 0.529 × 10⁻¹⁰ m ≈ 0.53 Å (0.053 nm). The radius of the nth orbit is n²a₀/Z.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-3","question":"In an n-type semiconductor the majority charge carriers are:","options":["Holes","Electrons","Protons","Positive ions"],"answer":1,"explanation":"Doping silicon or germanium with a pentavalent impurity (P, As, Sb) donates free electrons, which become the majority carriers; holes are the minority carriers. The crystal as a whole remains electrically neutral.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-modern-physics-4","question":"The energy of a photon of wavelength 6200 Å is approximately (hc = 12400 eV·Å):","options":["1 eV","2 eV","3 eV","0.5 eV"],"answer":1,"explanation":"E = hc/λ = 12400/6200 = 2 eV. This is red light; visible photons carry roughly 1.6–3.2 eV.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-5","question":"A radioactive sample has a half-life of 10 days. The fraction of the original nuclei that remain undecayed after 30 days is:","options":["1/3","1/4","1/8","1/16"],"answer":2,"explanation":"30 days is 3 half-lives, so the remaining fraction is (1/2)³ = 1/8. The fraction decayed is 7/8.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-modern-physics-6","question":"The energy of the electron in the second orbit (n = 2) of a hydrogen atom is:","options":["−13.6 eV","−6.8 eV","−3.4 eV","−1.51 eV"],"answer":2,"explanation":"E_n = −13.6/n² eV, so E₂ = −13.6/4 = −3.4 eV. Dividing by n instead of n² gives the wrong −6.8 eV; −1.51 eV is E₃.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-7","question":"The energy equivalent of one atomic mass unit (1 u) is approximately:","options":["931.5 eV","931.5 keV","931.5 MeV","931.5 GeV"],"answer":2,"explanation":"From E = mc², 1 u = 1.66 × 10⁻²⁷ kg corresponds to about 931.5 MeV. This conversion is used directly to get binding energy from mass defect.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-modern-physics-8","question":"Which logic gate gives an output of 0 only when both of its inputs are 1?","options":["AND","OR","NOR","NAND"],"answer":3,"explanation":"NAND is NOT(A AND B): the output is 1 for inputs 00, 01 and 10, and 0 only for 11. NOR gives 1 only for 00.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-modern-physics-9","question":"When a p–n junction diode is forward biased:","options":["The depletion region widens and the barrier potential increases","The depletion region narrows and the barrier potential decreases","The depletion region widens and the barrier potential decreases","The depletion region is unchanged but the barrier potential decreases"],"answer":1,"explanation":"Forward bias (p to positive, n to negative) pushes majority carriers towards the junction, neutralising part of the space charge: the depletion layer narrows and the potential barrier falls, so a large current flows. Reverse bias does the opposite.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-10","question":"Light of wavelength 3100 Å falls on a metal of work function 2 eV. The stopping potential is (hc = 12400 eV·Å):","options":["2 V","1 V","4 V","6 V"],"answer":0,"explanation":"Photon energy = 12400/3100 = 4 eV. K_max = hν − φ = 4 − 2 = 2 eV, so the stopping potential is 2 V. The 4 V option is the photon energy, not the stopping potential.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-11","question":"The de Broglie wavelength of an electron accelerated from rest through a potential difference of 150 V is approximately:","options":["1 Å","0.1 Å","10 Å","1 nm"],"answer":0,"explanation":"λ = h/√(2meV) = 12.27/√V Å = 12.27/√150 ≈ 12.27/12.25 ≈ 1.0 Å, comparable to atomic spacing in crystals, which is why electrons of this energy show diffraction (Davisson–Germer).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-12","question":"The wavelength of the first line of the Balmer series (n = 3 → n = 2) of hydrogen is (Rydberg constant R = 1.097 × 10⁷ m⁻¹):","options":["486 nm","1875 nm","122 nm","656 nm"],"answer":3,"explanation":"1/λ = R(1/2² − 1/3²) = R × 5/36, so λ = 36/(5 × 1.097 × 10⁷) ≈ 6.56 × 10⁻⁷ m = 656 nm (the red H-α line). 486 nm is the second Balmer line and 122 nm is the first Lyman line.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-13","question":"The activity of a radioactive sample falls to 1/16 of its initial value in 40 minutes. Its half-life is:","options":["2.5 min","5 min","10 min","20 min"],"answer":2,"explanation":"Activity ∝ number of nuclei. 1/16 = (1/2)⁴, so 40 minutes is 4 half-lives and T₁/₂ = 10 min.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-14","question":"An X-ray tube operates at 31 kV. The shortest wavelength of X-rays produced is (hc = 12400 eV·Å):","options":["0.4 Å","4 Å","0.04 Å","2.5 Å"],"answer":0,"explanation":"The cut-off wavelength corresponds to an electron giving all its kinetic energy to one photon: λ_min = hc/(eV) = 12400/31000 = 0.4 Å. It depends only on the tube voltage, not on the target material.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-15","question":"The ratio of the nuclear radii of ²⁷Al and ⁶⁴Cu is:","options":["27 : 64","1 : 2","9 : 16","3 : 4"],"answer":3,"explanation":"R = R₀A^(1/3), so R_Al/R_Cu = (27/64)^(1/3) = 3/4. Nuclear volume is proportional to A, which is why nuclear density is the same for all nuclei.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-16","question":"A silicon diode with a forward voltage drop of 0.7 V is connected in series with a 1 kΩ resistor across a 5 V battery in forward bias. The current in the circuit is:","options":["5 mA","5.7 mA","0.7 mA","4.3 mA"],"answer":3,"explanation":"The diode takes 0.7 V, leaving 5 − 0.7 = 4.3 V across the resistor: I = 4.3/1000 = 4.3 mA. Treating the diode as ideal gives 5 mA.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-17","question":"The output of a NOR gate is fed to a NOT gate. The combination is equivalent to:","options":["AND gate","XOR gate","NAND gate","OR gate"],"answer":3,"explanation":"NOR gives NOT(A + B); inverting it again gives A + B, which is OR. Similarly NAND followed by NOT gives AND.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-18","question":"Given the masses m_p = 1.0073 u, m_n = 1.0087 u and that of the deuteron m_d = 2.0136 u, the binding energy of the deuteron is approximately (1 u = 931 MeV):","options":["1.1 MeV","8.8 MeV","4.5 MeV","2.2 MeV"],"answer":3,"explanation":"Mass defect Δm = (1.0073 + 1.0087) − 2.0136 = 0.0024 u. Binding energy = 0.0024 × 931 ≈ 2.2 MeV, i.e. about 1.1 MeV per nucleon (the deuteron is very loosely bound compared with the ~8 MeV per nucleon of medium nuclei).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-19","question":"How many of the following statements about the photoelectric effect are correct? (A) The stopping potential depends on the frequency of the light but not on its intensity. (B) For frequencies above the threshold, the photocurrent is proportional to the intensity. (C) Photoemission is practically instantaneous, with a delay of less than about 10⁻⁹ s. (D) At constant intensity, increasing the frequency increases the number of photoelectrons emitted per second.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A), (B) and (C) are correct. (D) is wrong: at fixed intensity, higher-frequency photons carry more energy each, so there are fewer photons per second and fewer electrons are emitted; only their maximum kinetic energy increases.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-20","question":"The energy required to remove the electron from a singly ionised helium atom (He⁺) when it is in its first excited state is:","options":["3.4 eV","6.8 eV","54.4 eV","13.6 eV"],"answer":3,"explanation":"For a hydrogen-like ion E_n = −13.6 Z²/n² eV. For He⁺ (Z = 2) in the first excited state (n = 2): E = −13.6 × 4/4 = −13.6 eV, so 13.6 eV is needed. 54.4 eV is the ground-state ionisation energy of He⁺; 3.4 eV is for hydrogen in n = 2.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-21","question":"Light of wavelength 2480 Å falls on a metal of work function 3.5 eV. The minimum de Broglie wavelength of the emitted photoelectrons is approximately (hc = 12400 eV·Å):","options":["5 Å","10 Å","1 Å","2.5 Å"],"answer":1,"explanation":"Photon energy = 12400/2480 = 5 eV, so K_max = 5 − 3.5 = 1.5 eV. The fastest electrons have the shortest de Broglie wavelength: λ = 12.27/√K Å = 12.27/√1.5 ≈ 10 Å.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-22","question":"In the radioactive decay chain ²³⁸U (Z = 92) → ²⁰⁶Pb (Z = 82), the numbers of α and β⁻ particles emitted are respectively:","options":["8 and 6","6 and 8","8 and 8","6 and 6"],"answer":0,"explanation":"Mass number falls by 238 − 206 = 32, and only α-decay changes A (by 4 each), so 8 α-particles. Eight α-decays would reduce Z by 16 to 76; the observed Z = 82 needs 6 β⁻ decays, each raising Z by 1.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-23","question":"The fraction of a radioactive sample that decays in a time equal to its mean life is approximately:","options":["50%","63%","37%","100%"],"answer":1,"explanation":"Mean life τ = 1/λ, and N = N₀e^(−λt) gives N/N₀ = e⁻¹ ≈ 0.37 at t = τ. So about 37% remains and 63% has decayed. The mean life is 1.44 times the half-life, so more than half has decayed.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-24","question":"Assertion (A): The density of nuclear matter is nearly the same for all nuclei. Reason (R): The nuclear radius varies as A^(1/3), so the nuclear volume is proportional to the mass number A.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Mass ∝ A and volume = (4/3)πR₀³A ∝ A, so the density (about 2.3 × 10¹⁷ kg/m³) is independent of A. R is the direct explanation of A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-25","question":"Match the spectral series of hydrogen (List I) with the region of the electromagnetic spectrum in which it lies (List II). List I: (P) Lyman; (Q) Balmer; (R) Paschen; (S) Pfund. List II: (1) visible; (2) ultraviolet; (3) far infrared; (4) near infrared.","options":["P-2, Q-1, R-4, S-3","P-1, Q-2, R-4, S-3","P-2, Q-1, R-3, S-4","P-2, Q-4, R-1, S-3"],"answer":0,"explanation":"Transitions to n = 1 (Lyman) are the most energetic, in the UV; to n = 2 (Balmer) in the visible; to n = 3 (Paschen) in the near IR; to n = 4 (Brackett) and n = 5 (Pfund) progressively further into the infrared.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-26","question":"A 10 V Zener diode is used as a voltage regulator with a 500 Ω series resistor and a 20 V unregulated supply. A 1 kΩ load is connected across the Zener diode. The current through the Zener diode is:","options":["20 mA","10 mA","30 mA","5 mA"],"answer":1,"explanation":"The Zener holds 10 V across the load. Current through the series resistor = (20 − 10)/500 = 20 mA; load current = 10/1000 = 10 mA. The remaining 20 − 10 = 10 mA flows through the Zener diode.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-27","question":"A logic circuit has output Y = 1 when exactly one of its two inputs A and B is 1, and Y = 0 when both are 0 or both are 1. The Boolean expression for Y is:","options":["A·B","A + B","A·B̄ + Ā·B","(A + B)̄"],"answer":2,"explanation":"This is the exclusive-OR (XOR) truth table: Y = A·B̄ + Ā·B, equivalently (A + B)·(A·B)̄. A + B (OR) would also give 1 for the 11 input, and A·B (AND) gives 1 only for 11.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-28","question":"The accelerating voltage across an X-ray tube is doubled, keeping the target the same. Which of the following is correct?","options":["Both the cut-off wavelength and the K_α wavelength are halved","The cut-off wavelength is halved; the K_α wavelength is unchanged","The cut-off wavelength is unchanged; the K_α wavelength is halved","Both are unchanged; only the intensity doubles"],"answer":1,"explanation":"λ_min = hc/(eV) depends only on the tube voltage and halves when V doubles. The characteristic K_α line comes from transitions between inner shells of the target atom and is fixed by the target's atomic number (Moseley's law), so it does not shift.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-29","question":"Each fission of a ²³⁵U nucleus releases about 200 MeV. The energy released by the complete fission of 1 g of ²³⁵U is approximately (Avogadro number = 6.02 × 10²³, 1 eV = 1.6 × 10⁻¹⁹ J):","options":["8.2 × 10¹⁰ J","8.2 × 10¹³ J","3.2 × 10⁻¹¹ J","2.6 × 10²¹ J"],"answer":0,"explanation":"Number of nuclei in 1 g = 6.02 × 10²³/235 ≈ 2.56 × 10²¹. Energy per fission = 200 × 10⁶ × 1.6 × 10⁻¹⁹ = 3.2 × 10⁻¹¹ J. Total = 2.56 × 10²¹ × 3.2 × 10⁻¹¹ ≈ 8.2 × 10¹⁰ J, roughly the energy from burning 2500 tonnes of coal.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-30","question":"In the Bohr model of hydrogen, the ratio of the time period of revolution of the electron in the n = 2 orbit to that in the n = 1 orbit is:","options":["2 : 1","4 : 1","8 : 1","1 : 8"],"answer":2,"explanation":"r ∝ n² and v ∝ 1/n, so T = 2πr/v ∝ n³. T₂/T₁ = 2³ = 8 : 1; the orbital frequency in n = 2 is one-eighth of that in the ground state.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-31","question":"Isotopes of an element have the same:","options":["atomic number","mass number","nuclear mass","number of neutrons"],"answer":0,"explanation":"Isotopes (e.g. ¹H, ²H, ³H) have the same number of protons, i.e. the same Z, but different numbers of neutrons and hence different mass numbers.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-modern-physics-32","question":"A radioactive nuclide has a half-life of 6.93 hours. Its decay constant is:","options":["1 per hour","0.693 per hour","0.1 per hour","10 per hour"],"answer":2,"explanation":"λ = ln 2/T½ = 0.693/6.93 = 0.1 h⁻¹. The mean life is 1/λ = 10 h.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-modern-physics-33","question":"The energy of the photon emitted when the electron in a hydrogen atom jumps from n = 2 to n = 1 is:","options":["12.09 eV","10.2 eV","3.4 eV","13.6 eV"],"answer":1,"explanation":"E₂ − E₁ = −3.4 − (−13.6) = 10.2 eV, the first Lyman line. 12.09 eV is the n = 3 → 1 transition.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-34","question":"Hydrogen atoms are excited to the n = 5 level. The maximum number of different spectral lines they can emit while returning to the ground state is:","options":["4","6","15","10"],"answer":3,"explanation":"Number of lines = n(n − 1)/2 = 5 × 4/2 = 10. A single atom can emit at most 4 lines (one per jump), but a sample emits all possible transitions.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-modern-physics-35","question":"The energy required to remove the electron from a Li²⁺ ion in its ground state is:","options":["30.6 eV","13.6 eV","40.8 eV","122.4 eV"],"answer":3,"explanation":"For a hydrogen-like ion E₁ = −13.6Z² eV; with Z = 3, the ionisation energy is 13.6 × 9 = 122.4 eV. 30.6 eV wrongly scales with Z instead of Z².","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-36","question":"Two radioactive samples A and B start with equal numbers of nuclei. Their half-lives are 1 h and 2 h respectively. After 4 hours, the ratio of undecayed nuclei N_A/N_B is:","options":["1/2","1/16","1/4","4"],"answer":2,"explanation":"After 4 h, A has gone through 4 half-lives (1/16 left) and B through 2 (1/4 left). Ratio = (1/16)/(1/4) = 1/4.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-37","question":"In a transistor in common-emitter configuration the current gain β is 50. If the base current is 20 μA, the emitter current is:","options":["1.02 mA","1.20 mA","0.98 mA","1.00 mA"],"answer":0,"explanation":"I_C = βI_B = 50 × 20 μA = 1 mA, and I_E = I_B + I_C = 1.02 mA. 1 mA is the collector current.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-38","question":"The work function of a metal is 4.14 eV. Taking hc = 12400 eV Å, its threshold wavelength for photoemission is about:","options":["2000 Å","4140 Å","5000 Å","3000 Å"],"answer":3,"explanation":"λ₀ = hc/φ = 12400/4.14 ≈ 2995 Å ≈ 3000 Å. Light of longer wavelength cannot eject electrons, however intense it is.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-39","question":"A hydrogen atom at rest emits a photon in the n = 2 → n = 1 transition (10.2 eV). Taking the mass of the atom as 1.67 × 10⁻²⁷ kg, the recoil speed of the atom is about:","options":["6.5 m/s","3.3 m/s","33 m/s","0.33 m/s"],"answer":1,"explanation":"The photon's momentum is E/c, so the atom recoils with v = E/(mc) = 10.2 × 1.6 × 10⁻¹⁹/(1.67 × 10⁻²⁷ × 3 × 10⁸) = 1.63 × 10⁻¹⁸/5.01 × 10⁻¹⁹ ≈ 3.3 m/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-40","question":"A nucleus of mass number 226, at rest, undergoes α-decay with a Q-value of 4.87 MeV. The kinetic energy of the emitted α-particle is about:","options":["4.87 MeV","4.78 MeV","4.70 MeV","0.09 MeV"],"answer":1,"explanation":"Momentum conservation shares Q in inverse ratio to mass: K_α = Q × (A − 4)/A = 4.87 × 222/226 ≈ 4.78 MeV. The daughter nucleus takes the remaining ≈ 0.09 MeV.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-41","question":"How many of the following statements are correct?\n(A) Nuclear forces are nearly independent of the charge of the nucleons.\n(B) The binding energy per nucleon is greatest for nuclei with mass number around 56.\n(C) Nuclear density increases with the mass number.\n(D) In β⁻ decay a neutron changes into a proton, emitting an electron and an antineutrino.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B (iron region, about 8.8 MeV per nucleon) and D are correct. C is wrong: since R = R₀A^(1/3), the volume is proportional to A and nuclear density is nearly the same for all nuclei. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-modern-physics-42","question":"The output of a NAND gate with inputs A and B is fed to both inputs of a second NAND gate. The combination behaves as:","options":["a NOT gate","a NOR gate","an AND gate","an OR gate"],"answer":2,"explanation":"A NAND gate with its inputs tied together is a NOT gate, so the output is NOT(NOT(A·B)) = A·B, an AND gate.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-modern-physics-43","question":"The ratio of the longest wavelength of the Lyman series to the shortest wavelength of the Balmer series of hydrogen is:","options":["4 : 9","1 : 3","5 : 27","1 : 4"],"answer":1,"explanation":"Longest Lyman line (2 → 1): 1/λ = R(1 − 1/4) = 3R/4, so λ = 4/3R. Shortest Balmer line (∞ → 2, the series limit): 1/λ = R/4, so λ = 4/R. Ratio = (4/3R)/(4/R) = 1/3. 5 : 27 compares the first lines of the two series instead.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-44","question":"The photon emitted when a He⁺ ion makes a transition from n = 2 to n = 1 falls on a hydrogen atom in its ground state. The kinetic energy of the electron ejected from the hydrogen atom is:","options":["30.6 eV","27.2 eV","13.6 eV","40.8 eV"],"answer":1,"explanation":"For He⁺ (Z = 2), E₂ − E₁ = 13.6 × 4 × (1 − 1/4) = 40.8 eV. This exceeds hydrogen's ionisation energy of 13.6 eV, so the electron leaves with 40.8 − 13.6 = 27.2 eV.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-45","question":"Assertion (A): The width of the depletion region of a p–n junction increases when it is forward biased.\nReason (R): In forward bias, the majority carriers are pushed towards the junction.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true, but A is false: in forward bias the majority carriers move towards the junction and neutralise part of the space charge, so the depletion region becomes narrower. It widens under reverse bias.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "phy-modern-physics-46", "question": "Which of the following has zero rest mass?", "options": ["Neutron", "Electron", "Photon", "α-particle"], "answer": 2, "explanation": "A photon always travels at c and has no rest mass, although it carries energy hν and momentum h/λ. The electron, neutron and α-particle all have rest mass.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-modern-physics-47", "question": "To make a p-type semiconductor, pure silicon is doped with:", "options": ["boron", "phosphorus", "arsenic", "antimony"], "answer": 0, "explanation": "A trivalent impurity such as boron accepts electrons and creates holes, giving a p-type semiconductor. P, As and Sb are pentavalent donors that give n-type material.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-modern-physics-48", "question": "A full-wave rectifier is fed from a 50 Hz AC supply. The fundamental frequency of the ripple in its output is:", "options": ["50 Hz", "25 Hz", "200 Hz", "100 Hz"], "answer": 3, "explanation": "A full-wave rectifier gives one output pulse for each half-cycle, so the ripple frequency is 2 × 50 = 100 Hz. A half-wave rectifier would give 50 Hz.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-modern-physics-49", "question": "A radioactive nucleus emits one α-particle and then two β⁻ particles. The resulting nucleus is:", "options": ["an isobar of the original nucleus", "an isotope of the original nucleus", "the same nuclide as the original", "an isotone of the original nucleus"], "answer": 1, "explanation": "The α-emission lowers Z by 2 and A by 4; the two β⁻ emissions raise Z by 2 and leave A alone. Z is back where it started and A is 4 less, so the product is an isotope.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-modern-physics-50", "question": "For a hydrogen atom in its ground state, the ratio of the ionisation energy to the first excitation energy is:", "options": ["3/4", "4/3", "2", "4"], "answer": 1, "explanation": "Ionisation energy = 13.6 eV; first excitation (n = 1 → 2) = 13.6 × (1 − 1/4) = 10.2 eV. The ratio is 13.6/10.2 = 4/3.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-modern-physics-51", "question": "In the Bohr model of the hydrogen atom, the ratio of the electron's speed in the first orbit to its speed in the third orbit is:", "options": ["1 : 3", "9 : 1", "1 : 9", "3 : 1"], "answer": 3, "explanation": "v_n = (2.18 × 10⁶ m/s) × Z/n, so the speed is inversely proportional to n: v₁/v₃ = 3. 9 : 1 is the ratio of the energies, which go as 1/n².", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-modern-physics-52", "question": "The binding energy per nucleon is greatest, at about 8.8 MeV, for nuclei near:", "options": ["⁵⁶Fe", "²³⁵U", "⁴He", "²H"], "answer": 0, "explanation": "The binding-energy curve peaks near A ≈ 56 (iron), which is why fusion of light nuclei and fission of heavy nuclei both release energy. ⁴He is an unusually stable light nucleus (≈ 7 MeV) but lies below the peak.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-modern-physics-53", "question": "Pure silicon has an intrinsic carrier concentration of 1.5 × 10¹⁶ m⁻³. It is doped with donor atoms to an electron concentration of 1 × 10²² m⁻³. The hole concentration in thermal equilibrium is:", "options": ["1.5 × 10¹⁶ m⁻³", "1 × 10²² m⁻³", "2.25 × 10¹⁰ m⁻³", "1.5 × 10⁶ m⁻³"], "answer": 2, "explanation": "By the law of mass action n_e n_h = n_i², so n_h = (1.5 × 10¹⁶)²/10²² = 2.25 × 10³²/10²² = 2.25 × 10¹⁰ m⁻³. Doping sharply reduces the minority carriers below the intrinsic level.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-modern-physics-54", "question": "A radioactive sample contains 10²⁰ undecayed nuclei, and the half-life is 693 s. The activity of the sample is:", "options": ["1.44 × 10²⁰ Bq", "6.93 × 10²² Bq", "10²⁰ Bq", "10¹⁷ Bq"], "answer": 3, "explanation": "λ = 0.693/T½ = 0.693/693 = 10⁻³ s⁻¹, so the activity A = λN = 10⁻³ × 10²⁰ = 10¹⁷ decays per second. 6.93 × 10²² Bq multiplies N by T½ instead of using λ.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-modern-physics-56", "question": "In a common-emitter transistor amplifier, the current gain is 100, the load resistance is 4 kΩ and the input resistance is 1 kΩ. The voltage gain is:", "options": ["100", "25", "400", "4"], "answer": 2, "explanation": "A_v = β × R_L/R_in = 100 × 4/1 = 400 (with the output inverted in phase). 4 is just the resistance ratio, without the current gain.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-modern-physics-57", "question": "Two deuterons fuse to form a ⁴He nucleus. The binding energies per nucleon are 1.1 MeV for the deuteron and 7.0 MeV for ⁴He. The energy released is:", "options": ["23.6 MeV", "5.9 MeV", "26.2 MeV", "4.8 MeV"], "answer": 0, "explanation": "Total binding energy before: 2 × (2 × 1.1) = 4.4 MeV; after: 4 × 7.0 = 28 MeV. Energy released = 28 − 4.4 = 23.6 MeV. 5.9 MeV wrongly subtracts the per-nucleon values (7.0 − 1.1).", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-modern-physics-58", "question": "A 10 V battery of negligible internal resistance is connected across two parallel branches, each containing a 5 Ω resistor. One branch also contains an ideal diode connected so that it is reverse biased. The current drawn from the battery is:", "options": ["4 A", "1 A", "2 A", "zero"], "answer": 2, "explanation": "An ideal reverse-biased diode is an open circuit, so only the other branch conducts: I = 10/5 = 2 A. 4 A would need both branches to conduct.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-modern-physics-59", "question": "Taking hc = 12400 eV Å, the wavelength of the photon emitted when the electron in a hydrogen atom jumps from n = 4 to n = 2 is about:", "options": ["4860 Å", "6560 Å", "1215 Å", "3650 Å"], "answer": 0, "explanation": "E = 13.6(1/4 − 1/16) = 13.6 × 3/16 = 2.55 eV, so λ = 12400/2.55 ≈ 4860 Å, the blue-green H-β line. 6560 Å is the n = 3 → 2 line (H-α).", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-modern-physics-60", "question": "How many of the following statements are correct?\n(A) The density of nuclear matter is about 2.3 × 10¹⁷ kg/m³.\n(B) In β⁻ decay, an electron and an antineutrino are emitted.\n(C) The emission of a γ-ray photon changes the atomic number of the nucleus.\n(D) The Sun's energy comes mainly from the fusion of hydrogen into helium.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and D are correct. C is wrong: γ-emission only carries away excitation energy, leaving both Z and A unchanged. Three are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-modern-physics-61", "question": "Hydrogen atoms in their ground state are bombarded with electrons of kinetic energy 12.5 eV. The number of spectral lines the atoms can then emit is:", "options": ["6", "1", "10", "3"], "answer": 3, "explanation": "Reaching n = 3 needs 12.09 eV, but n = 4 needs 12.75 eV, which is more than 12.5 eV. So the atoms reach at most n = 3 and can emit n(n − 1)/2 = 3 lines (3→2, 3→1, 2→1). 6 assumes n = 4 is reached.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-modern-physics-62", "question": "A radioactive nuclide decays into a stable daughter. Starting with the pure parent, after 24 hours the ratio of daughter nuclei to parent nuclei is 7 : 1. The half-life of the parent is:", "options": ["24 h", "8 h", "3.4 h", "12 h"], "answer": 1, "explanation": "A daughter-to-parent ratio of 7 : 1 means 1/8 of the parent is left, which takes 3 half-lives. T½ = 24/3 = 8 h. 3.4 h comes from taking 1/7 of the parent to be left.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-modern-physics-63", "question": "The total energy of the electron in a hydrogen atom is −1.51 eV. Its orbital angular momentum, according to Bohr's model, is:", "options": ["2h/2π", "3h/2π", "h/2π", "9h/2π"], "answer": 1, "explanation": "E_n = −13.6/n² = −1.51 eV gives n² = 9, so n = 3. Bohr's quantisation L = nh/2π gives L = 3h/2π.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-modern-physics-64", "question": "According to Moseley's law, the wavelength of the Kα X-ray line of an element with Z = 21 is λ. For an element with Z = 41 it is:", "options": ["λ/2", "4λ", "λ/√2", "λ/4"], "answer": 3, "explanation": "√ν ∝ (Z − 1), so λ ∝ 1/(Z − 1)². λ′/λ = (20/40)² = 1/4. Using Z instead of (Z − 1) would give (21/41)² instead.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-modern-physics-65", "question": "Inputs A and B are fed to an OR gate. Its output and the input A are then fed to an AND gate, whose output is Y. Then:", "options": ["Y = A, whatever the value of B", "Y = B, whatever the value of A", "Y = A · B", "Y = A + B"], "answer": 0, "explanation": "Y = (A + B) · A = A + A·B = A (the absorption law). Check: A = 0 gives Y = 0; A = 1 gives A + B = 1 and Y = 1, whatever B is.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-modern-physics-66", "question": "Assertion (A): A Zener diode can be used as a voltage regulator.\nReason (R): In the reverse breakdown region, the voltage across a Zener diode stays nearly constant over a wide range of current.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: connected in reverse bias across the load, the Zener takes more or less current as the input or load changes, while its voltage, and so the load voltage, stays nearly fixed.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-modern-physics-67", "question": "Match the device (List I) with how it is operated (List II).\nList I: (P) LED; (Q) photodiode; (R) Zener diode used as a voltage regulator; (S) solar cell.\nList II: (1) no external bias; it generates an emf itself; (2) forward biased; (3) reverse biased in the breakdown region; (4) reverse biased, below breakdown.", "options": ["P-4, Q-2, R-3, S-1", "P-2, Q-3, R-4, S-1", "P-2, Q-4, R-3, S-1", "P-2, Q-4, R-1, S-3"], "answer": 2, "explanation": "An LED emits light when forward biased; a photodiode works in reverse bias, where light changes the small reverse current noticeably; a Zener regulates in reverse breakdown; a solar cell needs no bias and produces its own photo-emf.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-modern-physics-68", "question": "A nuclear reactor produces 200 MW of power from the fission of ²³⁵U, with 200 MeV released per fission. The mass of ²³⁵U consumed per day is about:", "options": ["2.1 kg", "21 g", "0.21 g", "0.21 kg"], "answer": 3, "explanation": "Fissions per second = 2 × 10⁸/(200 × 1.6 × 10⁻¹³) = 6.25 × 10¹⁸. Per day that is 6.25 × 10¹⁸ × 86400 ≈ 5.4 × 10²³ fissions ≈ 0.90 mol, i.e. 0.90 × 235 ≈ 211 g ≈ 0.21 kg.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-modern-physics-69", "question": "In a common-emitter transistor, α = 0.98 and the base current is 40 μA. The collector current and the emitter current are about:", "options": ["2.0 mA and 1.96 mA", "1.96 mA and 2.0 mA", "3.92 mA and 3.96 mA", "39.2 μA and 40 μA"], "answer": 1, "explanation": "β = α/(1 − α) = 0.98/0.02 = 49, so I_C = 49 × 40 μA = 1.96 mA and I_E = I_C + I_B = 2.0 mA. Note that I_C/I_E = 0.98 = α, as it should.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-modern-physics-70", "question": "A photodiode is made of a semiconductor with a band gap of 2.8 eV (hc = 12400 eV Å). Which of the following wavelengths can it detect?", "options": ["6000 Å", "4000 nm", "4000 Å", "6000 nm"], "answer": 2, "explanation": "A photon must have E ≥ 2.8 eV, i.e. λ ≤ 12400/2.8 ≈ 4430 Å. Only 4000 Å (3.1 eV) qualifies; 6000 Å carries only about 2.07 eV, and 4000 nm and 6000 nm are infrared wavelengths with far less energy.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"phy-modern-physics-71","question":"The ratio of the wavelength of the first line of the Lyman series of He⁺ to that of the first line of the Lyman series of hydrogen is:","options":["1/4","1/2","4","2"],"answer":0,"explanation":"For hydrogen-like ions 1/λ = RZ²(1/n₁² − 1/n₂²). The same transition (2 → 1) in He⁺ (Z = 2) has 1/λ four times larger, so λ(He⁺)/λ(H) = 1/4. Answering 4 inverts the ratio.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-72","question":"A p–n junction diode is reverse biased (below breakdown). The small current through it is:","options":["due to majority carriers and increases steadily with the reverse voltage","due to minority carriers and nearly independent of the reverse voltage","due to majority carriers and nearly independent of the reverse voltage","exactly zero, because the depletion layer is an insulator"],"answer":1,"explanation":"The reverse bias raises the barrier for majority carriers, so only minority carriers drift across. Their number is set by thermal generation (temperature), so the current saturates at a small value almost independent of the voltage, until breakdown.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-73","question":"A radioactive sample initially contains N₀ nuclei and has half-life T. The number of nuclei that decay between t = T and t = 2T is:","options":["N₀/8","N₀/2","N₀/4","3N₀/4"],"answer":2,"explanation":"At t = T, N₀/2 remain; at t = 2T, N₀/4 remain. So N₀/2 − N₀/4 = N₀/4 decay during the second half-life. 3N₀/4 is the number decayed in the whole interval from 0 to 2T.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-74","question":"In the Bohr model of the hydrogen atom, the magnetic field produced at the nucleus by the orbiting electron in the nth orbit is proportional to:","options":["n⁻³","n⁻⁶","n⁻⁴","n⁻⁵"],"answer":3,"explanation":"B = μ₀I/(2r) with I = ev/(2πr), so B ∝ v/r². With v ∝ 1/n and r ∝ n², B ∝ n⁻¹/n⁴ = n⁻⁵. Forgetting that the current itself depends on r gives n⁻³.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-75","question":"A single hydrogen atom is in the n = 5 state. As it returns to the ground state by one or more spontaneous transitions, the largest number of photons it can emit is:","options":["4","5","10","1"],"answer":0,"explanation":"One atom follows a single cascade; it emits the most photons by stepping down one level at a time, 5 → 4 → 3 → 2 → 1, which gives 4 photons. The formula n(n − 1)/2 = 10 counts the different lines from a large sample of atoms, where different atoms take different routes.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-76","question":"Two radioactive samples, A of half-life 1 day and B of half-life 2 days, have equal activities at t = 0. After 2 days, their total activity as a fraction of the initial total activity is:","options":["1/4","3/8","1/2","3/4"],"answer":1,"explanation":"Activity of each falls by (1/2)^(t/T): A to 1/4 (two half-lives) and B to 1/2 (one half-life). Total = (1/4 + 1/2)/2 = 3/8 of the initial total. Averaging the half-lives (1.5 days) gives a wrong value.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-77","question":"An ideal diode is connected in parallel with a 4 Ω resistor, and this combination is in series with a 2 Ω resistor across a 6 V battery of negligible internal resistance. The battery current when the diode is forward biased and when the battery is reversed (diode reverse biased) is respectively:","options":["3 A and zero","1 A and 3 A","3 A and 1 A","1.5 A and 1 A"],"answer":2,"explanation":"Forward biased, the ideal diode short-circuits the 4 Ω resistor: I = 6/2 = 3 A. Reverse biased, it is an open circuit, so the 4 Ω carries the current: I = 6/(2 + 4) = 1 A. 'Zero' wrongly assumes the diode is in series with everything.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-78","question":"A transistor in common-emitter configuration has a current gain of 50, an input resistance of 1 kΩ and a load resistance of 5 kΩ. The power gain of the amplifier is:","options":["250","50","2500","12500"],"answer":3,"explanation":"Voltage gain = β R_L/R_in = 50 × 5 = 250, and power gain = current gain × voltage gain = 50 × 250 = 12500 (= β² R_L/R_in). 250 is only the voltage gain.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-79","question":"A nucleus of mass number 240 with binding energy per nucleon 7.6 MeV splits into two equal fragments, each with binding energy per nucleon 8.5 MeV. The energy released is about:","options":["216 MeV","108 MeV","0.9 MeV","1020 MeV"],"answer":0,"explanation":"Energy released = (total binding energy of products) − (that of the parent) = 2 × 120 × 8.5 − 240 × 7.6 = 2040 − 1824 = 216 MeV. 0.9 MeV is only the gain per nucleon, and 108 MeV counts one fragment.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-80","question":"An ideal half-wave rectifier is fed from a 220 V (rms) sinusoidal supply. The average (DC) value of the output voltage across the load is about:","options":["220 V","99 V","198 V","156 V"],"answer":1,"explanation":"V_m = 220√2 ≈ 311 V. Over a full cycle the half-wave output averages V_m/π ≈ 99 V. 198 V (= 2V_m/π) is the full-wave value and 156 V (= V_m/2) is the rms of the half-wave output.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-81","question":"A radioactive nuclide (decay constant λ) is produced in a reactor at a constant rate R nuclei per second, starting with none. After a time equal to one half-life, the number of these nuclei present is:","options":["RT/2, with T the half-life","R/λ","R/(2λ)","R/(λ ln 2)"],"answer":2,"explanation":"dN/dt = R − λN gives N = (R/λ)(1 − e^(−λt)). At t = T, e^(−λT) = 1/2, so N = R/(2λ), half the saturation value R/λ. RT/2 ignores the decay during production.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-82","question":"In a logic circuit, X = NAND(A, B), Y = NAND(A, X), Z = NAND(B, X), and the output is Out = NAND(Y, Z). The circuit behaves as:","options":["an XNOR gate","an AND gate","an OR gate","an XOR gate"],"answer":3,"explanation":"Truth table: A = B = 0 gives X = 1, Y = Z = 1, Out = 0; A = 0, B = 1 gives X = 1, Y = 1, Z = 0, Out = 1; similarly A = 1, B = 0 gives 1; A = B = 1 gives X = 0, Y = Z = 1, Out = 0. Output 1 only for unequal inputs: XOR. Stopping after two levels makes it look like OR.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-83","question":"The photon emitted when a He⁺ ion makes the transition n = 4 → n = 2 has the same wavelength as the photon emitted by a hydrogen atom in the transition:","options":["n = 2 → n = 1","n = 4 → n = 2","n = 3 → n = 2","n = 4 → n = 1"],"answer":0,"explanation":"He⁺: E = 13.6 × 4 × (1/4 − 1/16) = 13.6 × 3/4 = 10.2 eV. Hydrogen: 2 → 1 gives 13.6 × (1 − 1/4) = 10.2 eV as well (generally, n → m in He⁺ matches n/2 → m/2 in H). Assuming the same quantum numbers ignores the Z² factor.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-84","question":"A neutron collides head-on with a hydrogen atom at rest in its ground state. Taking the masses as equal, the minimum kinetic energy the neutron must have so that the collision can excite the atom is:","options":["10.2 eV","20.4 eV","27.2 eV","13.6 eV"],"answer":1,"explanation":"Momentum must be conserved, so the most kinetic energy that can be converted into internal energy is in a perfectly inelastic collision: for equal masses that is K/2. K/2 ≥ 10.2 eV (the first excitation energy) gives K ≥ 20.4 eV. 10.2 eV forgets that the atom must also recoil.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-85","question":"Radium-226 (half-life 1600 years) decays to radon-222 (half-life 3.8 days). In an old sealed sample the two are in secular equilibrium. The ratio of the number of radon nuclei to the number of radium nuclei is about:","options":["1","2.4 × 10⁻³","6.5 × 10⁻⁶","1.5 × 10⁵"],"answer":2,"explanation":"In secular equilibrium the activities are equal: λ_Rn N_Rn = λ_Ra N_Ra, so N_Rn/N_Ra = T_Rn/T_Ra = 3.8 days/(1600 × 365 days) ≈ 6.5 × 10⁻⁶. 2.4 × 10⁻³ forgets to convert years to days; 1 assumes equal numbers rather than equal activities.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-86","question":"A nuclide decays by two independent modes, α-emission and β-emission. If only α-decay occurred, its half-life would be 3 h; if only β-decay occurred, 6 h. Its actual half-life is:","options":["4.5 h","3 h","9 h","2 h"],"answer":3,"explanation":"The decay constants add: λ = λ_α + λ_β, so 1/T = 1/3 + 1/6 = 1/2 and T = 2 h. Averaging the half-lives (4.5 h) or adding them (9 h) is wrong; the actual half-life is shorter than either.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-87","question":"How many of the following statements about semiconductors are correct?\n(A) In an n-type semiconductor at room temperature the free-electron concentration is nearly equal to the donor concentration.\n(B) In a doped semiconductor in thermal equilibrium, the product of the electron and hole concentrations equals n_i², the square of the intrinsic concentration.\n(C) Doping silicon with a pentavalent impurity gives the crystal a net negative charge.\n(D) The band gap of silicon is smaller than that of germanium.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A (nearly all donors are ionised) and B (the mass-action law np = n_i²) are correct. C is wrong: each donor atom brings its own extra proton, so the crystal stays neutral. D is wrong: Si has about 1.1 eV and Ge about 0.7 eV.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-88","question":"How many of the following statements about radioactive decay are correct?\n(A) The activity of a sample halves in every half-life.\n(B) The decay constant of a nuclide can be changed appreciably by heating it strongly or raising the pressure.\n(C) After two mean lives, the fraction of nuclei left undecayed is 1/e².\n(D) In γ-decay the nucleus moves from an excited state to a lower state with no change in its mass number or atomic number.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, C (N = N₀e^(−t/τ), t = 2τ) and D are correct. B is wrong: decay is a nuclear process, practically unaffected by temperature, pressure or chemical state.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-89","question":"Assertion (A): The binding energy per nucleon decreases gradually for nuclei heavier than about A = 60.\nReason (R): The nuclear force between nucleons is short-range and saturates, while the Coulomb repulsion acts between every pair of protons and so grows roughly as Z².","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Each nucleon attracts only its near neighbours, so the nuclear binding per nucleon stops growing, while the electrostatic energy of Z protons grows as Z(Z − 1). In heavy nuclei the repulsion increasingly offsets the attraction, lowering BE/A (from about 8.8 MeV near Fe to about 7.6 MeV for U). R explains A.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-90","question":"Match the decay process (List I) with its description (List II).\nList I: (P) γ-decay; (Q) β⁺-decay; (R) electron capture; (S) β⁻-decay.\nList II: (1) Z increases by 1 and an antineutrino is emitted; (2) A and Z unchanged; (3) Z decreases by 1 and a positron and a neutrino are emitted; (4) Z decreases by 1 and only a neutrino is emitted (with characteristic X-rays from the atom).","options":["P-2, Q-3, R-4, S-1","P-2, Q-4, R-3, S-1","P-1, Q-3, R-4, S-2","P-2, Q-3, R-1, S-4"],"answer":0,"explanation":"γ-decay only releases excitation energy (A, Z unchanged). In β⁺ decay p → n + e⁺ + ν. In electron capture an inner electron is absorbed, p + e⁻ → n + ν, and the vacancy is filled with X-ray emission. In β⁻ decay n → p + e⁻ + antineutrino, raising Z by 1.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-91","question":"A neutron makes a head-on elastic collision with a deuterium nucleus (mass twice that of the neutron) at rest. The fraction of its kinetic energy that the neutron loses is:","options":["1/2","8/9","1/9","2/3"],"answer":1,"explanation":"After a head-on elastic collision the neutron's velocity is (m − 2m)/(m + 2m) = −1/3 of its initial value, so it keeps 1/9 of its kinetic energy and loses 8/9 (= 4m₁m₂/(m₁ + m₂)²). 1/9 is what it keeps, not what it loses.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-92","question":"Hydrogen atoms in their ground state are excited by monochromatic light. Afterwards, the most energetic photon they emit has an energy of 12.75 eV. The number of different lines of the Balmer series present in their emission spectrum is:","options":["3","1","2","6"],"answer":2,"explanation":"13.6(1 − 1/n²) = 12.75 eV gives n = 4, so the atoms were raised to n = 4. Balmer lines end on n = 2 and start from n = 3 or 4: two lines. 6 is the total number of lines (from n = 4 to all lower levels), not just Balmer.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-93","question":"An α-particle of kinetic energy 5 MeV moves head-on towards a gold nucleus (Z = 79). Taking e²/4πε₀ = 1.44 MeV fm, the distance of closest approach is about:","options":["22.7 fm","4.5 fm","91 fm","45.5 fm"],"answer":3,"explanation":"At closest approach all the kinetic energy is electrostatic potential energy: K = (2e)(79e)/(4πε₀ r), so r = 2 × 79 × 1.44/5 ≈ 45.5 fm. Forgetting that the α-particle carries charge 2e gives 22.7 fm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-94","question":"A free neutron decays as n → p + e⁻ + antineutrino. Given the neutron mass 1.008665 u, the mass of a neutral hydrogen atom ¹H as 1.007825 u, and 1 u = 931.5 MeV/c², the energy released (Q-value) is about:","options":["0.78 MeV","0.27 MeV","1.29 MeV","0.51 MeV"],"answer":0,"explanation":"The ¹H atom already contains one proton plus one electron, so m_p + m_e = m(¹H) and Q = (m_n − m(¹H))c² = 0.000840 × 931.5 ≈ 0.78 MeV. Subtracting the electron mass again (0.78 − 0.51) gives the trap 0.27 MeV.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-95","question":"Compare the electron in the n = 3 orbit of a Li²⁺ ion (Z = 3) with the electron in the n = 1 orbit of a hydrogen atom, using the Bohr model. The Li²⁺ electron has:","options":["nine times the energy and the same orbit radius","the same energy and the same orbital speed, but three times the orbit radius","the same energy, but three times the orbital speed","the same energy and the same orbit radius"],"answer":1,"explanation":"Bohr model: E ∝ Z²/n², v ∝ Z/n and r ∝ n²/Z. For Z = 3, n = 3: E ratio = 9/9 = 1, v ratio = 3/3 = 1, r ratio = 9/3 = 3. Equal energy does not mean an equal orbit, because the energy depends on Z²/n² while the radius depends on n²/Z.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-modern-physics-96","question":"Which statement about the nuclear force between nucleons is correct?","options":["It acts only between protons","It is a long-range force falling off as 1/r²","It is very strong but acts only over distances of a few femtometres","It is purely repulsive"],"answer":2,"explanation":"The strong nuclear force binds nucleons regardless of charge (p–p, n–n and p–n alike), is far stronger than the electric repulsion at about 1 fm, but dies away within a few fm (and becomes repulsive at very short range).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-modern-physics-97","question":"Of the radiations emitted by radioactive nuclei, the one that is most penetrating (needs the thickest lead to stop it) is:","options":["α-particles","γ-rays","β-particles","all three are equally penetrating"],"answer":1,"explanation":"γ-rays are uncharged, massless photons that interact only weakly, so they penetrate far more than β-particles, which in turn penetrate more than heavily ionising α-particles.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-modern-physics-98","question":"In the reaction ⁷Li + ¹H → 2 ⁴He, the atomic masses are ⁷Li = 7.016004 u, ¹H = 1.007825 u and ⁴He = 4.002603 u (1 u = 931.5 MeV/c²). The energy released is about:","options":["17.3 MeV","8.7 MeV","1.73 MeV","26.0 MeV"],"answer":0,"explanation":"Mass defect = 7.016004 + 1.007825 − 2 × 4.002603 = 0.018623 u. Q = 0.018623 × 931.5 ≈ 17.3 MeV, shared as kinetic energy by the two α-particles (8.7 MeV is each one's share).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-99","question":"Radium-226 has a half-life of 1600 years. The activity of 1 g of it is about (1 year ≈ 3.16 × 10⁷ s, Nₐ = 6.02 × 10²³ mol⁻¹):","options":["1.4 × 10⁻¹¹ Bq","3.7 × 10⁷ Bq","2.7 × 10²¹ Bq","3.7 × 10¹⁰ Bq"],"answer":3,"explanation":"N = 6.02 × 10²³/226 ≈ 2.66 × 10²¹ nuclei; λ = 0.693/(1600 × 3.16 × 10⁷ s) ≈ 1.37 × 10⁻¹¹ s⁻¹. A = λN ≈ 3.7 × 10¹⁰ Bq — this is the origin of the curie unit.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-100","question":"A sample of ancient wood shows a carbon-14 activity per gram of carbon that is 1/8 of that of living wood. Taking the half-life of ¹⁴C as 5730 years, the age of the wood is about:","options":["11,460 years","5730 years","45,800 years","17,200 years"],"answer":3,"explanation":"1/8 = (1/2)³, so three half-lives have passed: 3 × 5730 ≈ 17,200 years.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-modern-physics-101","question":"A radioactive nuclide P (decay constant 2λ) decays into Q, which is itself radioactive with decay constant λ and decays into a stable product. Starting with pure P at t = 0, the number of Q nuclei is maximum at:","options":["t = (ln 2)/(2λ)","t = 1/λ","t = (ln 2)/λ","t = 2/λ"],"answer":2,"explanation":"N_Q ∝ e^(−λ₂t) − e^(−λ₁t). Setting dN_Q/dt = 0 gives t = ln(λ₁/λ₂)/(λ₁ − λ₂) = ln 2/(2λ − λ) = (ln 2)/λ. At that instant the two activities are equal.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-102","question":"In the Bohr model, the electron in the ground state of hydrogen moves at 2.19 × 10⁶ m/s in an orbit of radius 0.529 Å. The equivalent current due to its orbital motion is about:","options":["1.05 A","1.05 mA","6.6 mA","0.17 mA"],"answer":1,"explanation":"Orbital frequency f = v/(2πr) = 2.19 × 10⁶/(2π × 0.529 × 10⁻¹⁰) ≈ 6.6 × 10¹⁵ Hz. Current I = ef = 1.6 × 10⁻¹⁹ × 6.6 × 10¹⁵ ≈ 1.05 × 10⁻³ A.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-103","question":"Positronium is a bound system of an electron and a positron (equal masses) orbiting their common centre of mass. Using the Bohr model with reduced mass, its ground-state energy is about:","options":["−6.8 eV","−13.6 eV","−27.2 eV","−3.4 eV"],"answer":0,"explanation":"Bohr energies are proportional to the reduced mass. For hydrogen μ ≈ mₑ; for positronium μ = mₑ/2. So E₁ = −13.6/2 = −6.8 eV, and the separation in the ground state is twice the hydrogen Bohr radius.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-104","question":"In a 'muonic hydrogen' atom, a muon (mass about 207 electron masses, same charge) replaces the electron. Ignoring the reduced-mass correction, the ground-state energy of this atom is about:","options":["−2.8 keV","−13.6 eV","−66 eV","−2.8 MeV"],"answer":0,"explanation":"Bohr energy E ∝ m and radius r ∝ 1/m. So E₁ = −13.6 × 207 eV ≈ −2.8 keV, and the orbit is 207 times smaller (about 2.6 × 10⁻¹³ m), so the muon spends appreciable time near the nucleus.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-105","question":"Hydrogen atoms are excited to the n = 6 level. The number of different spectral lines they can emit that belong to the Balmer series is:","options":["10","5","15","4"],"answer":3,"explanation":"Balmer lines end on n = 2. The possible upper levels are n = 3, 4, 5 and 6, giving 4 Balmer lines. (The total number of lines from n = 6 is 6 × 5/2 = 15.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-106","question":"Hydrogen atoms in the n = 2 state absorb photons of energy 2.55 eV. The excited atoms then return to the ground state. The total number of different wavelengths that can be emitted is:","options":["4","3","6","10"],"answer":2,"explanation":"−3.4 + 2.55 = −0.85 eV = −13.6/4², so the atoms reach n = 4. From n = 4, all transitions down to n = 1 are possible: 4 × 3/2 = 6 different lines (including the Lyman lines, even though the atoms were excited from n = 2).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-107","question":"Using Moseley's law with the screening constant 1, the energy of the Kα X-ray photon from copper (Z = 29) is about:","options":["8.6 keV","8.0 keV","11.4 keV","0.4 keV"],"answer":1,"explanation":"Kα corresponds to n = 2 → 1 in an effective charge (Z − 1): E = 13.6(Z − 1)²(1 − 1/4) eV = 10.2 × 28² ≈ 8.0 keV. Using Z instead of Z − 1 gives 8.6 keV.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-108","question":"Taking the nuclear radius as R = 1.2 A^(1/3) fm and the nucleon mass as 1.66 × 10⁻²⁷ kg, the density of nuclear matter is about:","options":["2.3 × 10¹⁴ kg/m³","2.3 × 10¹⁷ kg/m³","2.3 × 10³ kg/m³","2.3 × 10²⁰ kg/m³"],"answer":1,"explanation":"Mass A × 1.66 × 10⁻²⁷ kg occupies (4/3)π(1.2 × 10⁻¹⁵)³A m³. The A cancels: ρ = 1.66 × 10⁻²⁷/7.24 × 10⁻⁴⁵ ≈ 2.3 × 10¹⁷ kg/m³, the same for all nuclei.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-109","question":"Two deuterons must come into contact (surfaces just touching, R = 1.2 A^(1/3) fm each) for fusion. Taking e²/4πε₀ = 1.44 MeV fm, the Coulomb barrier they must overcome is about:","options":["0.48 MeV","1.2 MeV","0.24 MeV","0.96 MeV"],"answer":0,"explanation":"Each deuteron has R = 1.2 × 2^(1/3) ≈ 1.51 fm, so the centres are 3.02 fm apart. U = 1.44/3.02 ≈ 0.48 MeV, far more than typical thermal energies, which is why fusion needs temperatures of ~10⁷–10⁸ K (and quantum tunnelling).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-110","question":"In β⁻ decay, the emitted electrons have a continuous range of kinetic energies up to a maximum value. This observation led to the proposal that:","options":["the daughter nucleus is left in many excited states","energy is not conserved in nuclear processes","the electron was already present inside the nucleus","a third, nearly undetectable particle (the antineutrino) shares the released energy"],"answer":3,"explanation":"If only the electron and the recoiling nucleus were produced, momentum and energy conservation would fix the electron's energy uniquely. A continuous spectrum means the energy is shared with a third particle, the (anti)neutrino, which carries off the remainder.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-111","question":"Silicon is doped with 1 × 10²² donor atoms per m³, all ionised. Taking the electron mobility as 0.135 m²/(V s) and neglecting the holes, the conductivity of the doped silicon is about:","options":["0.216 S/m","2.16 S/m","216 S/m","2.16 × 10⁴ S/m"],"answer":2,"explanation":"σ = neμₑ = 10²² × 1.6 × 10⁻¹⁹ × 0.135 ≈ 216 S/m, millions of times the conductivity of pure silicon at room temperature.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-112","question":"A bridge rectifier using four silicon diodes (forward drop 0.7 V each) is fed with an AC voltage of peak value 10 V. The peak voltage across the load is about:","options":["10 V","9.3 V","8.6 V","7.2 V"],"answer":2,"explanation":"In a bridge rectifier, two diodes conduct in series in each half-cycle, so the peak output is 10 − 2 × 0.7 = 8.6 V.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-modern-physics-113","question":"A silicon transistor (β = 100) in common-emitter mode has a collector resistor of 1 kΩ connected to a 5 V supply. The base current is 100 μA. The collector current is approximately:","options":["10 mA","5 mA, as the transistor is saturated","1 mA","zero, as the transistor is cut off"],"answer":1,"explanation":"βI_B = 10 mA would need a drop of 10 V across 1 kΩ, more than the 5 V supply. The transistor therefore saturates (V_CE ≈ 0) and I_C is limited by the circuit to about 5/1000 = 5 mA; the relation I_C = βI_B holds only in the active region.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-114","question":"A logic circuit gives Y = (A + B)·(A + B̄), where + is OR, · is AND and B̄ is NOT B. This simplifies to:","options":["Y = A","Y = B","Y = A + B","Y = 1"],"answer":0,"explanation":"Expanding: A·A + A·B̄ + B·A + B·B̄ = A + A(B̄ + B) + 0 = A + A = A. (Equivalently, by the distributive law, (A + B)(A + B̄) = A + B·B̄ = A.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-115","question":"A light-emitting diode is made of a semiconductor with a band gap of 1.9 eV. Taking hc = 1240 eV nm, the light it emits is about:","options":["1240 nm, infrared","450 nm, blue","550 nm, green","650 nm, red"],"answer":3,"explanation":"Electrons and holes recombining across the gap emit photons of energy ≈ E_g. λ = 1240/1.9 ≈ 650 nm, in the red.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-modern-physics-116","question":"In a nuclear reactor, a fast neutron collides elastically and head-on with a stationary carbon-12 nucleus in the graphite moderator. The fraction of its kinetic energy that the neutron loses is about:","options":["0.5","0.72","0.08","0.28"],"answer":3,"explanation":"For a head-on elastic collision with a nucleus of mass A (in neutron masses), the neutron keeps the fraction [(A − 1)/(A + 1)]² = (11/13)² ≈ 0.72 of its energy and loses about 0.28. Light nuclei (H, D, C) are good moderators.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-117","question":"Both the fission of uranium and the fusion of hydrogen isotopes release energy. The reason is that:","options":["both processes convert neutrons into protons","both processes reduce the number of nucleons","in both cases the products have a larger binding energy per nucleon than the reactants","both processes increase the total mass"],"answer":2,"explanation":"The binding energy per nucleon peaks near A ≈ 56–62. Splitting a heavy nucleus or fusing light ones both move towards this peak, so the products are more tightly bound and the mass difference appears as released energy; the nucleon number is conserved.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-118","question":"A hydrogen-like ion emits a photon of energy 108.8 eV when its electron drops from the second excited state to the ground state. The ion is:","options":["He⁺ (Z = 2)","Li²⁺ (Z = 3)","Be³⁺ (Z = 4)","H (Z = 1)"],"answer":1,"explanation":"The second excited state is n = 3. E = 13.6Z²(1 − 1/9) = 12.09Z² eV. Setting this to 108.8 eV gives Z² = 9, Z = 3.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-119","question":"In the Bohr model, the electron in the ground state of hydrogen moves at about 2.19 × 10⁶ m/s. The speed of the electron in the n = 2 orbit of a He⁺ ion is:","options":["2.19 × 10⁶ m/s","4.38 × 10⁶ m/s","1.1 × 10⁶ m/s","8.76 × 10⁶ m/s"],"answer":0,"explanation":"Bohr speed v ∝ Z/n. For He⁺ (Z = 2) in n = 2, Z/n = 1, so the speed is the same as in the hydrogen ground state: 2.19 × 10⁶ m/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-modern-physics-120","question":"As the temperature of a pure semiconductor such as germanium increases, its resistance:","options":["decreases, because more electron–hole pairs are produced","increases, because of more frequent collisions","remains constant","first increases and then becomes zero"],"answer":0,"explanation":"Thermal energy excites more electrons across the band gap, increasing the carrier concentration exponentially. This outweighs the reduced mobility, so the resistivity falls — a negative temperature coefficient, unlike metals.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-modern-physics-121","question":"In an atom, the photon wavelengths for the transitions 3 → 2, 2 → 1 and 3 → 1 are λ₃₂, λ₂₁ and λ₃₁. They are related by:","options":["1/λ₃₁ = 1/λ₃₂ − 1/λ₂₁","λ₃₁ = λ₃₂ + λ₂₁","λ₃₁ = √(λ₃₂λ₂₁)","1/λ₃₁ = 1/λ₃₂ + 1/λ₂₁"],"answer":3,"explanation":"Energies add: E₃₁ = E₃₂ + E₂₁. Since E = hc/λ, this gives 1/λ₃₁ = 1/λ₃₂ + 1/λ₂₁ (the Ritz combination principle). Wavelengths themselves do not add.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-122","question":"The nuclei ¹⁴C (Z = 6) and ¹⁴N (Z = 7) are an example of:","options":["isotones","isotopes","isobars","isomers"],"answer":2,"explanation":"They have the same mass number A = 14 but different atomic numbers, so they are isobars. (¹⁴C has 8 neutrons and ¹⁴N has 7, so they are not isotones either.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-modern-physics-123","question":"The longest wavelength of light that can ionise a hydrogen atom already in its n = 3 state is about (hc = 1240 eV nm):","options":["91 nm","820 nm","365 nm","656 nm"],"answer":1,"explanation":"Ionisation from n = 3 needs 13.6/9 ≈ 1.51 eV. λ_max = 1240/1.51 ≈ 820 nm, in the infrared. (91 nm is needed from the ground state, 365 nm from n = 2.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-modern-physics-124","question":"The reaction ¹⁴N + α → ¹⁷O + p has a Q-value of −1.19 MeV. For α-particles fired at stationary ¹⁴N nuclei, the threshold kinetic energy needed (using masses 4 u and 14 u) is about:","options":["1.19 MeV","1.53 MeV","0.93 MeV","5.35 MeV"],"answer":1,"explanation":"Momentum conservation means the products must keep the CM kinetic energy, so more than |Q| is needed. Threshold K = |Q|(1 + m_α/m_N) = 1.19 × (1 + 4/14) ≈ 1.53 MeV.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-125","question":"A single radioactive nucleus has a half-life of 1 hour. The probability that it is still undecayed after 2 hours is:","options":["1/4","zero","1/2","it cannot be stated, since a single nucleus has no half-life"],"answer":0,"explanation":"Decay is random and memoryless: each half-life the survival probability halves, independent of age. After two half-lives it is (1/2)² = 1/4. The half-life is a property of each nucleus, expressed as a probability.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-126","question":"A nucleus ᴬ_ZX emits one α-particle and then one positron (β⁺). The final nucleus has:","options":["atomic number Z − 3 and mass number A − 5","atomic number Z − 1 and mass number A − 4","atomic number Z − 2 and mass number A − 5","atomic number Z − 3 and mass number A − 4"],"answer":3,"explanation":"α-emission: Z → Z − 2, A → A − 4. β⁺ emission converts a proton into a neutron: Z decreases by 1 more, A unchanged. Final: Z − 3, A − 4.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-modern-physics-127","question":"In the Bohr model of hydrogen (r₁ = 0.529 Å), the de Broglie wavelength of the electron in the n = 3 orbit is about:","options":["30 Å","3.3 Å","10 Å","1.1 Å"],"answer":2,"explanation":"Bohr's condition is that n de Broglie wavelengths fit round the orbit: nλ = 2πrₙ. With r₃ = 9 × 0.529 = 4.76 Å, λ = 2π × 4.76/3 ≈ 10 Å.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-modern-physics-128","question":"In the Bohr model, the ratio of the radius of the first orbit of He⁺ to the radius of the second orbit of Li²⁺ is:","options":["1 : 2","8 : 3","3 : 8","3 : 4"],"answer":2,"explanation":"rₙ ∝ n²/Z. He⁺, n = 1: 1/2. Li²⁺, n = 2: 4/3. Ratio = (1/2)/(4/3) = 3/8.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
